6	use super::constants::REKEY_TIMEOUT;
7	use super::wireguard::WireGuard;
8	use super::workers::HandshakeJob;
9	
10	use std::fmt;
11	use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
12	use std::time::{Instant, SystemTime};
13	
14	use spin::{Mutex, RwLock, RwLockReadGuard, RwLockWriteGuard};
15	
16	use x25519_dalek::PublicKey;
17	
18	pub struct PeerInner<T: Tun, B: UDP> {
19	    // internal id (for logging)
20	    pub id: u64,
21	
22	    // wireguard device state
23	    pub wg: WireGuard<T, B>,
24	
25	    // TODO: eliminate
26	    pub pk: PublicKey,
27	
28	    // handshake state
29	    pub walltime_last_handshake: Mutex<Option<SystemTime>>, /* walltime for last handshake (for UAPI status) */
30	    pub last_handshake_sent: Mutex<Instant>,                // instant for last handshake
31	    pub handshake_queued: AtomicBool,                       // is a handshake job currently queued?
32	
33	    // stats and configuration
34	    pub rx_bytes: AtomicU64, // received bytes
35	    pub tx_bytes: AtomicU64, // transmitted bytes
36	
37	    // timer model
38	    pub timers: RwLock<Timers>,
39	}
40	
41	impl<T: Tun, B: UDP> PeerInner<T, B> {
42	    /* Queue a handshake request for the parallel workers
43	     * (if one does not already exist)
44	     *
45	     * The function is ratelimited.
46	     */
47	    pub fn packet_send_handshake_initiation(&self) {
48	        log::trace!("{} : packet_send_handshake_initiation", self);
49	
50	        // the function is rate limited
51	        {
52	            let mut lhs = self.last_handshake_sent.lock();
53	            if lhs.elapsed() < REKEY_TIMEOUT {
54	                log::trace!("{} : packet_send_handshake_initiation, rate-limited!", self);
55	                return;
56	            }
57	            *lhs = Instant::now();
58	        }
59	
60	        // create a new handshake job for the peer
61	        if !self.handshake_queued.swap(true, Ordering::SeqCst) {
62	            self.wg.pending.fetch_add(1, Ordering::SeqCst);
63	            self.wg.queue.send(HandshakeJob::New(self.pk));
64	            log::trace!(
65	                "{} : packet_send_handshake_initiation, handshake queued",
66	                self
67	            );
68	        } else {
69	            log::trace!(
70	                "{} : packet_send_handshake_initiation, handshake already queued",
71	                self
72	            );
73	        }
74	    }
75	
76	    #[inline(always)]
77	    pub fn timers(&self) -> RwLockReadGuard<Timers> {
78	        self.timers.read()
79	    }
80	
81	    #[inline(always)]
82	    pub fn timers_mut(&self) -> RwLockWriteGuard<Timers> {
83	        self.timers.write()
84	    }
85	}
86	
87	impl<T: Tun, B: UDP> fmt::Display for PeerInner<T, B> {
88	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
89	        write!(f, "peer(id = {})", self.id)
90	    }
